const LV={1:'Interface',2:'Fléchettes',3:'Conséquences',4:'Tour',5:'Exploits',6:'Fin de partie'};
const DUR={tic:.7,retour:.8,erreur:.9,arm:1.4,simple:.9,double:1,triple:1.2,spew:1.2,tspew:2,ferme:1.6,points:1.1,touche:1.4,tour:1.1,petit:2.1,grand:3.4,victoire:3.8,defaite:2.6};
function playNew(fk,k){const F=FAM[fk],t=AC.currentTime+.04,R=F.root;
  const hits=n=>{for(let i=0;i<n;i++)F.imp(t+i*.095,i);F.note(t+(n-1)*.095+.02,fq(R,n*2-2+7),.18,.35)};
  ({tic:()=>F.tic(t),
    retour:()=>{F.note(t,fq(R,4),.1,.6);F.note(t+.08,fq(R,1),.16,.6)},
    erreur:()=>{F.note(t,R/2,.14,.8);F.note(t+.004,R/2*1.0595,.14,.6);F.note(t+.13,R/2*.94,.2,.8);F.note(t+.134,R/2*.94*1.0595,.2,.6)},
    arm:()=>{F.arm(t,2);F.arm(t+.55,3)},
    simple:()=>hits(1),double:()=>hits(2),triple:()=>hits(3),
    spew:()=>F.spew(t),
    tspew:()=>{F.spew(t);F.spew(t+.2);F.spew(t+.4);F.hurt(t+.75)},
    ferme:()=>F.close(t),points:()=>F.points(t),touche:()=>F.hurt(t),tour:()=>F.turn(t),
    petit:()=>F.small(t),grand:()=>F.big(t),victoire:()=>F.win(t),defaite:()=>F.lose(t)})[k]()}
function play(fk,e){audioInit();if(!AC)return;if(fk==='actuel'){try{e.old()}catch(x){}}else playNew(fk,e.k)}
/* ===================== UNIVERS ÉCHANTILLONNÉS =====================
   vrais instruments enregistrés (banque FluidR3 GM), rejoués, superposés, transposés, réverbérés.
   un événement = [instrument, note MIDI (ou tableau = accord), départ (s), options]
   options : v volume · d durée avant extinction · pan · room/hall réverbe · lp filtre · bend demi-tons (glissé) · st décalage des notes d'un accord */
const roll=(i,n,count,t0,step,acc,v0,v1,o={})=>Array.from({length:count},(_,k)=>{let t=t0;for(let j=0;j<k;j++)t+=step*Math.pow(acc,j);return[i,n,t,Object.assign({},o,{v:v0+(v1-v0)*k/Math.max(1,count-1)})]});
const arp=(i,ns,t0,step,o={})=>ns.map((n,k)=>[i,n,t0+k*step,o]);
