add2('Rap','lowrider','Victoire · G-funk lent (lowrider)',()=>{const t=T0(),B=60/86,s=B/4,sw=s*.2,q=i=>t+i*s+(i%2?sw:0);for(let i=0;i<32;i++)if(i%2===0)hat(q(i),i%4===2?.12:.07,.2);
  [0,7,10,16,23,26].forEach(i=>dkick(q(i),.8));[4,12,20,28].forEach(i=>{dsnare(q(i),.42);clap(q(i)+.012,.22)});
  [[0,33,.9],[7,33,.3],[10,36,.6],[16,38,.9],[23,38,.3],[26,40,.6]].forEach(([i,n,d])=>b808(q(i),n,d*B*1.3,.3));
  [[0,[57,60,64,67,71]],[16,[62,65,69,72,76]]].forEach(([i,ch])=>ch.forEach((n,k)=>one('electric_piano_1',n,q(i)+k*.014,{v:.3,d:B*3.8,room:.3})));
  whine(q(1),[[0,76,B*1.1],[B*1.2,81,B*.9],[B*2.2,79,B*.5],[B*2.8,76,B*.6],[B*3.5,74,B*.4],[B*4,76,B*3]],.12)});
add2('Rap','talk','Victoire · talk-box funk',()=>{const t=T0(),B=60/96,s=B/4;for(let i=0;i<32;i+=2)hat(t+i*s,.08,.2);[0,10,16,26].forEach(i=>dkick(t+i*s,.85));[4,12,20,28].forEach(i=>{dsnare(t+i*s,.45);clap(t+i*s,.2)});
  [[0,36,1],[6,36,.4],[10,43,.6],[16,41,1],[22,41,.4],[26,39,.6]].forEach(([i,n,d])=>b808(t+i*s,n,d*B*1.3,.3));
  [[2,72,'u','a',.9],[6,75,'a','o',.5],[8,77,'o','a',1.4],[18,79,'u','i',.6],[21,77,'i','a',.6],[24,75,'a','u',1.6]].forEach(([i,n,v1,v2,d])=>talk(t+i*s,n,d*B,v1,v2,.16))});
add2('Rap','hydro','Nouveau meneur · suspensions hydrauliques',()=>{const t=T0();[0,.3,.6].forEach((dt,i)=>{N(t+dt,{v:.25,d:.12,type:'highpass',f:1500});b808(t+dt,31+i*2,.28,.45);V(t+dt+.03,mid(55+i*3),{type:'sawtooth',v:.06,d:.2,f2:mid(60+i*3),glide:.15,lp:2000})})});
add2('Rap','whistle2','Exploit · sifflement + clap',()=>{const t=T0(),B=60/94;whine(t,[[0,81,B*.5],[B*.55,84,B*.5],[B*1.1,81,B*1.2]],.13);clap(t+B,.4);dkick(t+B,.8);b808(t+B,36,B*1.2,.35)});
