add2('Rap','t808w','Triple · 3 coups de 808 + sifflement',()=>{const t=T0();[0,.15,.3].forEach((dt,i)=>{dkick(t+dt,.8+i*.07);b808(t+dt,31+i*3,.3,.42);clap(t+dt,.2+i*.08)});whine(t+.32,[[0,84,.2],[.22,81,.5]],.11)});

/* ===================== CATALOGUES THÉMATIQUES — 2e série ===================== */
const engN=(t,rpm,cyl,o={})=>{const pts=rpm.map(([dt,r])=>[dt,r/60*cyl/2]);sweepOsc(t,pts,Object.assign({type:'sawtooth',v:.15,lp:3000,q:2,drive:1,uni:3,det:16},o));sweepOsc(t,pts.map(([d,f])=>[d,f*2]),Object.assign({},o,{type:'square',v:(o.v||.15)*.35,lp:5000,uni:1}));if(cyl>=10)sweepOsc(t,pts.map(([d,f])=>[d,f*3]),Object.assign({},o,{type:'sawtooth',v:(o.v||.15)*.2,lp:7000,uni:1}))};
const pops=(t,n=4,v=.5)=>{for(let k=0;k<n;k++){const d=t+k*.07+Math.random()*.03;N(d,{kind:'brown',v,d:.05,type:'lowpass',f:1200});N(d,{v:v*.4,d:.02,f:2500,q:1})}};
const whoosh=(t,dur=.35,v=.3,f1=500,f2=3000,pan0=0,pan1=0)=>{N(t,{v,a:dur*.6,d:dur*.4,f:f1,f2,q:1.6,pan:pan0});if(pan1)N(t+dur*.3,{v:v*.5,a:dur*.3,d:dur*.4,f:f2,f2:f1,q:1.6,pan:pan1})};
const thunk=(t,v=.7,f=140)=>{V(t,f,{v,d:.12,f2:f*.55,glide:.08});N(t,{kind:'brown',v:v*.6,d:.07,type:'lowpass',f:900});N(t,{v:v*.25,d:.015,f:2200,q:2})};
const plate=(t,f=880,v=.35,pan=0)=>{bell(t,f,{v,ratio:2.76,idx:3,d:1.4,pan,room:.25});bell(t,f*1.5,{v:v*.4,ratio:1.41,idx:2,d:.8,pan});N(t,{v:v*.5,d:.01,type:'highpass',f:4000})};
const solenoid=(t,v=.5)=>{N(t,{v,d:.012,f:3000,q:2});V(t,90,{v:v*.9,d:.07,f2:60,glide:.05});N(t+.004,{kind:'brown',v:v*.5,d:.05,type:'lowpass',f:600})};
const chime=(t,which,v=.55)=>{const f={10:1318.5,100:987.8,1000:659.3}[which];bell(t,f,{v:v*.5,ratio:3.0,idx:1.4,d:1.6,room:.2});one('tubular_bells',Math.round(69+12*Math.log2(f/440)),t,{v:v*.6,d:1.4,room:.2});solenoid(t,.25)};
const knocker=(t,v=.9)=>{V(t,95,{v,d:.12,f2:55,glide:.06});N(t,{kind:'brown',v,d:.08,type:'lowpass',f:700});N(t,{v:v*.5,d:.02,f:1600,q:1.5,room:.4,hall:.2})};
const reels=(t,n=8,v=.3,step=.045)=>{for(let k=0;k<n;k++){N(t+k*step,{v,d:.01,f:2600,q:3});V(t+k*step,1200,{v:v*.15,d:.015})}};
const syl=(t,n,d,v1,v2,v=.17,c='')=>{if(c==='t'||c==='k'||c==='p')N(t,{v:v*.9,d:.02,type:'highpass',f:c==='t'?4000:c==='k'?2000:900});if(c==='s')N(t,{v:v*.7,d:.06,type:'highpass',f:5000});if(c==='b'||c==='d')V(t,mid(n-12),{v:v*.8,d:.03});talk(t+(c?.015:0),n,d,v1,v2,v)};
const VW=['a','e','i','o','u'],CS=['t','k','p','s','b','d','','',''];
const babble=(t,count,base,spread,step,v=.17,rise=0)=>{let x=0;for(let k=0;k<count;k++){const n=base+Math.round((Math.random()-.5)*spread)+Math.round(rise*k/Math.max(1,count-1)),d=step*(.7+Math.random()*.6);
  syl(t+x,n,d,VW[Math.random()*5|0],VW[Math.random()*5|0],v,CS[Math.random()*CS.length|0]);x+=d+.015}return x};
const laugh=(t,base=67,n=5,v=.17)=>{for(let k=0;k<n;k++)syl(t+k*.13,base-k,.09,'a','a',v,'')};
const tts=(txt,rate=1.1,pitch=1)=>{try{const u=new SpeechSynthesisUtterance(txt);u.lang='fr-FR';u.rate=rate;u.pitch=pitch;const vs=speechSynthesis.getVoices().filter(v=>/^fr/i.test(v.lang));if(vs[0])u.voice=vs[0];speechSynthesis.cancel();speechSynthesis.speak(u)}catch(e){}};
const twang=(t,v=.5,f=98)=>{pluck(t,f,{v,d:.9,bright:.3,room:.2});V(t,f,{type:'triangle',v:v*.3,d:.25,f2:f*.97,glide:.2})};
const arrowfly=(t,dur=.32,v=.3)=>N(t,{v,a:.04,h:dur*.6,d:dur*.3,f:1800,f2:3200,q:6,pan:-.3});
const target=(t,v=.8)=>{thunk(t,v,120);N(t+.01,{v:v*.3,d:.12,f:300,q:2})};
const gun=(t,v=.9,tail=.6,lp=0)=>{one('gunshot',60,t,{v,d:tail,lp:lp||0,room:.2,hall:.2});N(t,{v:v*.35,d:.03,type:'highpass',f:2000});V(t,90,{v:v*.5,d:.12,f2:45,glide:.1})};
const pump=(t,v=.5)=>{N(t,{v,d:.05,f:1200,q:2});N(t+.03,{kind:'brown',v,d:.06,type:'lowpass',f:700});N(t+.16,{v,d:.04,f:1800,q:2});N(t+.18,{kind:'brown',v:v*.8,d:.05,type:'lowpass',f:800})};
const click=(t,v=.4)=>{N(t,{v,d:.008,f:3500,q:4});N(t+.01,{v:v*.4,d:.01,f:1500,q:3})};
const crowdOle=(t,n=3)=>{for(let k=0;k<n;k++){crowd(t+k*.9,{dur:.45,v:.35,vow:'o',up:1});crowd(t+k*.9+.4,{dur:.5,v:.4,vow:'e',up:1})}};
const vuvu=(t,dur=1.6,v=.08)=>{for(let k=0;k<5;k++)V(t+k*.08,233*(1+(Math.random()-.5)*.03),{type:'sawtooth',v,a:.08,h:dur,d:.3,lp:1600,q:2,pan:Math.random()*1.6-.8,room:.3})};
const net=(t,v=.35)=>{N(t,{v,a:.01,d:.35,f:2500,f2:900,q:.8});N(t+.05,{kind:'pink',v:v*.6,d:.4,type:'bandpass',f:600,q:.5})};
const glove=(t,v=.6)=>{N(t,{kind:'pink',v,d:.07,f:900,q:1});V(t,200,{v:v*.4,d:.06,f2:120,glide:.05})};
const gravel=(t,dur=1,v=.35)=>{for(let k=0;k<dur*60;k++)N(t+Math.random()*dur,{v:v*Math.random(),d:.015,f:900+Math.random()*1800,q:2})};

